td.t-attf-style:
{{
                            'background-color: #fff3cd; -webkit-print-color-adjust: exact; print-color-adjust: exact;' if visit.status == 'planned'
                            else 'background-color: #d1e7dd; -webkit-print-color-adjust: exact; print-color-adjust: exact;' if visit.status == 'done'
                            else 'background-color: #f8d7da; -webkit-print-color-adjust: exact; print-color-adjust: exact;' if visit.status == 'cancelled'
                            else ''
                        }}
